package whatwgurl

import "testing"

// TestRandomIDNACorpus replays the deterministic 50,000-case punycode/Bidi/
// joiner/escape/reference corpus generated by tools/idna-random-cases.mts with
// Node's real new URL. It is a broader complement to the reviewer corpora and
// the exhaustive single-code-point fixture.
func TestRandomIDNACorpus(t *testing.T) {
	cases := readGzipCorpus(t, "testdata/random-idna-corpus.json.gz")
	if len(cases) != 50000 {
		t.Fatalf("random IDNA corpus has %d cases, want 50000", len(cases))
	}
	failures := 0
	fail := func(format string, args ...any) {
		failures++
		if failures <= 20 {
			t.Errorf(format, args...)
		}
	}
	for index, tc := range cases {
		var parsed *URL
		var err error
		if tc.Base == "" {
			parsed, err = Parse(tc.Input)
		} else {
			parsed, err = ParseRef(tc.Input, tc.Base)
		}
		if (err != nil) != tc.Throws {
			fail("%s[%d]: parse error = %v, Node throws = %v (%q base %q)",
				tc.ID, index, err, tc.Throws, tc.Input, tc.Base)
			continue
		}
		if tc.Throws {
			continue
		}
		got := [11]string{parsed.Href(), parsed.Origin(), parsed.Protocol(),
			parsed.Username(), parsed.Password(), parsed.Host(), parsed.Hostname(),
			parsed.Port(), parsed.Pathname(), parsed.Search(), parsed.Hash()}
		want := [11]string{tc.Href, tc.Origin, tc.Protocol, tc.Username, tc.Password,
			tc.Host, tc.Hostname, tc.Port, tc.Pathname, tc.Search, tc.Hash}
		if got != want {
			fail("%s[%d]: got %#v, want %#v (%q base %q)", tc.ID, index, got, want, tc.Input, tc.Base)
		}
	}
	if failures > 20 {
		t.Errorf("%d total random-corpus mismatches (first 20 shown)", failures)
	}
}
